preConditions.sqlCheck:
SELECT COUNT(*)
FROM pg_constraint
WHERE conname = 'uk_refresh_tokens_user';

changeSet.sql:
ALTER TABLE "refresh_tokens"
ADD CONSTRAINT uk_refresh_tokens_user
UNIQUE (user_id);

CREATE INDEX idx_timetable_academic_year
    ON "timetable" (academic_year_id);

CREATE INDEX idx_timetable_grade
    ON "timetable" (grade_id);

CREATE INDEX idx_timetable_section
    ON "timetable" (section_id);

CREATE INDEX idx_timetable_subject
    ON "timetable" (subject_id);

CREATE INDEX idx_timetable_faculty
    ON "timetable" (faculty_id);

CREATE INDEX idx_timetable_day
    ON "timetable" (day_of_week);

CREATE INDEX idx_class_session_timetable
    ON "class_session" (timetable_id);

CREATE INDEX idx_class_session_date
    ON "class_session" (session_date);

CREATE INDEX idx_class_session_status
    ON "class_session" (status);

CREATE INDEX IF NOT EXISTS idx_timetable_start_date
    ON "timetable" (start_date);

CREATE INDEX IF NOT EXISTS idx_timetable_end_date
    ON "timetable" (end_date);

ALTER TABLE "timetable"
    ADD CONSTRAINT chk_timetable_date_range
        CHECK (end_date >= start_date);

CREATE INDEX IF NOT EXISTS idx_attendance_session
    ON "attendance" (class_session_id);

CREATE INDEX IF NOT EXISTS idx_attendance_student
    ON "attendance" (student_id);

CREATE INDEX IF NOT EXISTS idx_attendance_status
    ON "attendance" (status);
